import{_ as e,o as i,c as s,ao as a}from"./chunks/framework.CwrF1Ikc.js";const g=JSON.parse('{"title":"Profiling","description":"","frontmatter":{},"headers":[],"relativePath":"profiling.md","filePath":"profiling.md","lastUpdated":null}'),n={name:"profiling.md"};function l(d,t,h,r,o,p){return i(),s("div",null,[...t[0]||(t[0]=[a(`<h1 id="Profiling" tabindex="-1">Profiling <a class="header-anchor" href="#Profiling" aria-label="Permalink to &quot;Profiling {#Profiling}&quot;">​</a></h1><p><a href="https://github.com/WaterLily-jl/WaterLily-Benchmarks/blob/main/profile.sh" target="_blank" rel="noreferrer"><code>profile.sh</code></a> profiles the solver kernels on NVIDIA GPUs. The kernels, generated by <a href="https://github.com/JuliaGPU/KernelAbstractions.jl" target="_blank" rel="noreferrer">KernelAbstractions.jl</a>, are traced with <a href="https://github.com/JuliaGPU/NVTX.jl" target="_blank" rel="noreferrer">NVTX.jl</a> ranges, which live in the <a href="https://github.com/WaterLily-jl/WaterLily.jl/tree/profiling" target="_blank" rel="noreferrer"><code>profiling</code></a> branch of WaterLily. <code>profile.sh</code> checks out that branch in <code>$WATERLILY_DIR</code> and updates its environment, whatever <code>-w</code> says.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./profile.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ns</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nsys</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;tgv sphere cylinder&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;8 5 6&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./profile.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ns</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ncu</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cylinder</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;4,5,6&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 20</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -k</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;327 355&quot;</span></span></code></pre></div><p>The runs use the CUDA environment, <code>gpu/CUDA</code>, which <code>profile.sh</code> makes again on every call (see <a href="./environments">Environments</a>), and the plots use the plotting environment, which has to be instantiated once.</p><h2 id="Options" tabindex="-1">Options <a class="header-anchor" href="#Options" aria-label="Permalink to &quot;Options {#Options}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Option</th><th style="text-align:right;">Default</th><th style="text-align:right;">Meaning</th></tr></thead><tbody><tr><td style="text-align:right;"><code>-ns</code>, <code>--nsight</code></td><td style="text-align:right;"><code>nsys</code></td><td style="text-align:right;"><code>nsys</code>, <code>ncu</code>, or both: <code>&quot;nsys ncu&quot;</code></td></tr><tr><td style="text-align:right;"><code>-r</code>, <code>--run</code></td><td style="text-align:right;"><code>0</code></td><td style="text-align:right;"><code>0</code> post-processes existing data, <code>1</code> profiles, <code>2</code> profiles and then post-processes</td></tr><tr><td style="text-align:right;"><code>-c</code>, <code>--cases</code></td><td style="text-align:right;">none</td><td style="text-align:right;">cases to profile</td></tr><tr><td style="text-align:right;"><code>-p</code>, <code>--log2p</code></td><td style="text-align:right;">none</td><td style="text-align:right;">sizes, one entry per case; comma-separated sizes are profiled one by one with <code>ncu</code></td></tr><tr><td style="text-align:right;"><code>-s</code>, <code>--max_steps</code></td><td style="text-align:right;"><code>1000</code></td><td style="text-align:right;">time steps</td></tr><tr><td style="text-align:right;"><code>-ft</code>, <code>--float_type</code></td><td style="text-align:right;"><code>Float32</code></td><td style="text-align:right;">float type</td></tr><tr><td style="text-align:right;"><code>-k</code>, <code>--kernels</code></td><td style="text-align:right;">none</td><td style="text-align:right;">kernels to profile with <code>ncu</code>, e.g. <code>&quot;327 355&quot;</code></td></tr><tr><td style="text-align:right;"><code>-b</code>, <code>--backends</code></td><td style="text-align:right;"><code>CuArray</code></td><td style="text-align:right;">backend</td></tr><tr><td style="text-align:right;"><code>-v</code>, <code>--versions</code></td><td style="text-align:right;">the <code>julia</code> on the <code>PATH</code></td><td style="text-align:right;">Julia version</td></tr><tr><td style="text-align:right;"><code>-wd</code>, <code>--waterlily_dir</code></td><td style="text-align:right;"><code>$WATERLILY_DIR</code></td><td style="text-align:right;">the WaterLily.jl clone</td></tr><tr><td style="text-align:right;"><code>-dd</code>, <code>--data_dir</code></td><td style="text-align:right;"><code>data/profiling</code></td><td style="text-align:right;">profiling data, one directory per case</td></tr><tr><td style="text-align:right;"><code>-pd</code>, <code>--plot_dir</code></td><td style="text-align:right;"><code>plots/profiling</code></td><td style="text-align:right;">plots of the post-processing</td></tr></tbody></table><h2 id="Nsight-Systems" tabindex="-1">Nsight Systems <a class="header-anchor" href="#Nsight-Systems" aria-label="Permalink to &quot;Nsight Systems {#Nsight-Systems}&quot;">​</a></h2><p>With <code>-ns nsys</code>, each case runs as</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nsys</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> profile</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --sample=none</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --trace=nvtx,cuda</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">data_dir</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">case</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">case</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">.nsys-rep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --export=sqlite</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force-overwrite=true</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> julia</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/profile.jl</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">case</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> argument</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">s</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>The post-processing (<code>-r 0</code> or <code>-r 2</code>) reads the time spent in each NVTX range with <code>nsys stats -r nvtx_gpu_proj_sum</code> and plots the share of each kernel with CairoMakie. The reports also open in the Nsight Systems GUI.</p><h2 id="Nsight-Compute" tabindex="-1">Nsight Compute <a class="header-anchor" href="#Nsight-Compute" aria-label="Permalink to &quot;Nsight Compute {#Nsight-Compute}&quot;">​</a></h2><p>With <code>-ns ncu</code>, the kernels given by <code>-k</code> are profiled with <code>ncu --set full</code>, one report per size in <code>&lt;data_dir&gt;/&lt;case&gt;/</code>. Open the reports in the Nsight Compute GUI.</p>`,12)])])}const k=e(n,[["render",l]]);export{g as __pageData,k as default};
